\label{Taniuchi Main theorem}[Taniuchi \cite{taniuchi2004},\cite{taniuchitashirotomoya2010}] Let $\theta:[1,\infty) \to [1,\infty)$ be a non-decreasing function such that 
\begin{equation}
\label{existence growth}
\int_1^{\infty} \frac{dp}{\theta(p)}=\infty.
\end{equation}
Then given $u_0 \in L^{\infty}(\mathbb{R}^2), \text{div }u_0=0, \omega_0 =\text{curl }u_0\in Y^{\theta}_{ul}(\mathbb{R}^2)$, there exists a weak solution $(u,p)$ of \eqref{E}
such that 
$$
\omega \in L^{\infty}_{loc}([0,\infty);Y^{^\theta}_{ul}(\mathbb{R}^2)), u \in L^{\infty}_{loc}([0,\infty);L^{\infty}(\mathbb{R}^2)),
$$
where 
\begin{equation}
\label{Pressure relation}
p=\sum_{k,l=1}^2 R_kR_lu^ku^l \text{ in } BMO(\mathbb{R}^2).
\end{equation}
Moreover, if $\theta$ satisfies 
\begin{equation}
\label{uniqueness growth}
\int_1^{\infty} \frac{dp}{p\theta(p)}=\infty,
\end{equation}
then the solution is unique.

In \cite{taniuchi2004}, the authors state in Remark $1$ that a similar result holds for solutions to the Navier-Stokes equations too. They claim that, if $\theta$ is of the form 
\[
\theta(p) = \underbrace{\log(e+p)\cdot \log(e+\log(e+p))\cdot \log(e+\log(e+\log(e+p)))\cdots,}_{\text{$k$ times iterated}}
\] 
then the solution to \eqref{NS} satisfies
\begin{equation}
\label{NS uly}
\left\lVertu^{\nu}(t)\right\rVert_{L^{\infty}} \leq C\left\lVertu_0\right\rVert_{L^{\infty}} \underbrace{\exp C \exp C \cdots \exp}_{\text{$k+2$ times}}\left\{Ct(\left\lVertu_0\right\rVert_{L^{\infty}} +1)(\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}}+1)^2\right\}.
\end{equation}
In the appendix, we extend this result to non-decreasing $\theta$ satisfying \eqref{existence growth}.
\\
\\
It is also important to note that estimate \eqref{NS uly} is independent of $\nu$. In particular, when we are establishing the inviscid limit, we are able to consider global solutions to the Euler and Navier-Stokes equations with regularity $(u,\omega) \in L^{\infty}(\mathbb{R}^2) \times Y^{\theta}_{ul}(\mathbb{R}^2)$, with uniform bounds that do not depend on the viscosity.

\label{main theorem}
Suppose that $u_0 \in L^{\infty}(\mathbb{R}^2)$ is divergence free and $\omega_0=\text{curl }u_0 \in Y^{\theta}_{ul}(\mathbb{R}^2)$ where $\theta$ is admissible in the sense of Definition \eqref{admissible theta}. 
Let $u^{\nu}$ and $u$ be global mild and weak solutions to \eqref{NS} and \eqref{E} respectively, generated from the same initial data, with $p^{\nu}$ and $p$ satisfying \eqref{Pressure relation}. Then for any $T>0$, the solution of \eqref{NS} converges to the solution of \eqref{E} in $L^{\infty}([0,T];L^2_{ul}(\mathbb{R}^2))$. In particular  
\begin{equation}
\label{main theorem equation}
\lim_{\nu \to 0^+} \sup_{t \in [0,T]} \left\lVert(u^{\nu}-u)(t)\right\rVert_{L^2_{ul}} = 0.
\end{equation}

\label{Osgood}
(Osgood's Lemma) Let $T>0 $, $\Psi$ a positive Borelian function, $\gamma$ a locally integrable positive function, and $\mu$ a continuous increasing function. Assume that for some number $\beta>0$ and for all $t\in[0,T]$, these functions satisfy $$\Psi(t)\leq\beta +\int_0^t\gamma(s)\mu(\Psi(s))\,ds.$$
Then for all $t\in[0,T]$ $$-\phi(\Psi(t))+\phi(\beta)\leq \int_0^t \gamma(s)\,ds,$$ where $\phi(x)=\int_x^1\frac{1}{\mu(r)}\,dr$.

(Bernstein's Lemma) Let $(r_1,r_2)$ be a pair of strictly positive real numbers such that $r_1<r_2$ and let $\lambda$ denote a positive real number. Then there exists a constant $C>0$, such that, for every integer $k$ with $k \geq 0$, every pair of real numbers $(a,b)$ satisfying $b \geq a \geq 1$, and every function $u \in L^a(\mathbb{R}^d)$,
\begin{enumerate}

\item 
\label{Bernstein in Ball}
If $\operatorname{supp}{\hat{u}} \subset B_{r_1\lambda}(0)$ then
\begin{equation*}
 \sup_{\mid\!\alpha\!\mid = k} \left\lVert\partial^{\alpha}u\right\rVert_{L^b} \leq C^k\lambda^{k+d(\frac{1}{a}-\frac{1}{b})}\left\lVertu\right\rVert_{L^a}.
\end{equation*}\\
\item 
\label{Bernstein in Annulus}
Furthermore, if $\operatorname{supp}{\hat{u}} \subset \mathcal{C}_{r_1\lambda, r_2\lambda}(0)$ then
\begin{equation*}
 C^{-k}\lambda^k\left\lVertu\right\rVert_{L^a} \leq  \sup_{\mid\!\alpha\!\mid = k} \left\lVert\partial^{\alpha}u\right\rVert_{L^a} \leq C^k\lambda^k\left\lVertu\right\rVert_{L^a}.
\end{equation*}
\end{enumerate}

We use the product rule to write 
\begin{equation}
\label{nfpk product rule}
\partial_i\partial_j(aG)(x) = (\partial_i\partial_ja)G + \partial_ia\partial_jG + \partial_ja\partial_iG + a\partial_i\partial_jG. 
\end{equation}
Recall that $\left\lVert\hat{f}\right\rVert_{L^{\infty}} \leq \left\lVertf\right\rVert_{L^1}$, and note that the first three terms on the RHS of \eqref{nfpk product rule} are in $L^1(\mathbb{R}^2)$ since $G\in W^{1,1}_{loc}(\mathbb{R}^2)$. We cannot employ this same technique to handle $a\partial_i\partial_jG$. Instead, we observe that
\begin{equation}
|\mathcal{F}(a\partial_i\partial_jG)(\xi)| \leq C \int_{\mathbb{R}^2} |\hat{a}(\xi-\eta)|\frac{|\eta_i\eta_j|}{|\eta|^2}\,d\eta \leq C\left\lVert\hat{a}\right\rVert_{L^1}.
\end{equation}

Let $(u,\omega)$ be the weak solution to \eqref{E} as in Theorem \ref{Taniuchi Main theorem}. Then for any $t\geq 0$, the pair $(u,\omega)$ satisfies
\begin{equation}
\label{FLSI}
u(t)=u_0+(aK)\ast(\omega(t)-\omega_0) - \int_0^t \nabla\nabla^{\perp}((1-a)K)\ast\cdot (u\otimes u)(s)\,ds.
\end{equation}

We begin by recalling that the solution $(u,\omega)$ arises from an approximating sequence $(u^{\varepsilon},\omega^{\varepsilon})$, which is constructed in \cite{taniuchi2004}. They show that $(u^{\varepsilon},\omega^{\varepsilon})$ satisfy the uniform bounds
\begin{equation}
\label{uniform bounds approx}
\begin{split}
\sup_{0 \leq t <T} \left\lVertu^{\varepsilon}(t)\right\rVert_{L^{\infty}} &\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T),\\
\sup_{0 \leq t <T} \left\lVert\omega^{\varepsilon}(t)\right\rVert_{L^p_{ul}} &\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T,p),\\ 
\end{split}
\end{equation} and for each $0<\delta<1, 0<t<T$
\begin{equation}
\label{uniform bound cts}
\begin{split}
\left\lVertu^{\varepsilon}(t)\right\rVert_{C^{1-\delta}}&\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)\\
\end{split}
\end{equation}
From \eqref{uniform bounds approx} and \eqref{uniform bound cts}, we see that there exists a subsequence $u^{\varepsilon_n}$ such that \begin{equation}
\begin{split}
\label{u convergence}
&u^{\varepsilon_n}\to u \quad \text{weak-$*$ in } L^{\infty}([0,T];L^{\infty}(\mathbb{R}^2))\\
&u^{\varepsilon_n}\to u\quad \text{strongly in } L^{\infty}([0,T];L^{\infty}(B_R(0))) \text{ for each } R>0
\text{ and } T>0.
\end{split}
\end{equation}
Furthermore, $u^{\varepsilon_n}$ satisfies
\begin{equation}
\label{approx sti eq1}
u^{\varepsilon_n}(t)=u_0^{\varepsilon_n} - \int_0^t \mathbb{P}\text{div }(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds.
\end{equation}
In what follows, we aim to show that $u^{\varepsilon_n}$ satisfies a Serfati-type identity, and then pass to the limit. We
let $G(x)=\frac{1}{2\pi}\log|x|$ so that $\Delta G=\delta_0$ and $K=\nabla^{\perp}G$, where $\delta_0$ is the Dirac-delta distribution. It follows that 
\begin{equation*}
\label{matrix kernel calculation}
\begin{split}
(\partial_l^{\perp}K_i)_{i,l=1}^2 &= \begin{pmatrix} \partial_2^2G & -\partial_1\partial_2G \\
-\partial_1\partial_2G & \partial_1^2G \end{pmatrix}\\
&=
\begin{pmatrix} \partial_1^2G+ \partial_2^2G & 0\\
0 & \partial_1^2G +\partial_2^2G\end{pmatrix}-
\begin{pmatrix} \partial_1^2G & \partial_1\partial_2G \\
\partial_1\partial_2G & \partial_2^2G \end{pmatrix}.\\
\end{split}
\end{equation*}
Hence, if $\delta_{il}$ is the Kronecker-delta function, we see that $\partial_l^{\perp}K_i = \delta_{il}\delta_0 - \partial_i\partial_lG $, which is the distributional kernel of $\mathbb{P}_{il}$. Substituting this into \eqref{approx sti eq1} gives
\begin{equation}
\label{approx sti eq2}
\begin{split}
u^{\varepsilon_n}(t)&=u_0^{\varepsilon_n} - \int_0^t \mathbb{P}\text{div }(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds \\
&= u_0^{\varepsilon_n} - \int_0^t \nabla\nabla^{\perp}K\ast\cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds\\
&=u_0^{\varepsilon_n} - \int_0^t \nabla\nabla^{\perp}(aK)\ast\cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds - \int_0^t \nabla\nabla^{\perp}((1-a)K)\ast\cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds.
\end{split}
\end{equation}
Since $u^{\varepsilon_n}$ and $\omega^{\varepsilon_n}$ are smooth, we see that 
$$
\partial_t((aK)\ast\omega^{\varepsilon_n})=(aK)\ast \partial_t\omega^{\varepsilon_n}=-(aK)\ast \text{curl div}(u^{\varepsilon_n}\otimes u^{\varepsilon_n}) = - \nabla\nabla^{\perp}(aK)\ast \cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n}). 
$$
Then, integrating in time one finds
\begin{equation}
\label{approx sti eq3}
 - \int_0^t \nabla\nabla^{\perp}(aK)\ast\cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds = (aK)\ast (\omega^{\varepsilon_n}(t)-\omega^{\varepsilon_n}_0).
 \end{equation}
 Combining \eqref{approx sti eq2} and \eqref{approx sti eq3} yields
 \begin{equation}
 \label{approx sti eq}
 u^{\varepsilon_n}(t)=u^{\varepsilon_n}_0 + (aK) \ast (\omega^{\varepsilon_n}(t) - \omega_0^{\varepsilon_n}) - \int_0^t \nabla \nabla^{\perp}((1-a)K) \ast \cdot (u^{\varepsilon_n}\otimes u^{\varepsilon_n})(s)\,ds.
 \end{equation}
We aim to pass to the limit in \eqref{approx sti eq}. To do this, we first show a form of local weak convergence for the vorticity. From \eqref{u convergence}, we see that for any $t \in [0,T]$ and $\psi \in C_c^{\infty}(\mathbb{R}^2)$
\begin{equation}
\label{vorticity distributional convergence}
\lim_{n \to \infty} \left |\int_{\mathbb{R}^2} (\omega^{\varepsilon_n}(t,x)-\omega(t,x))\psi(x)\,dx\right| \leq \lim_{n \to \infty} \left\lVert(u^{\varepsilon_n}(t)-u(t))\right\rVert_{L^{\infty}(\text{supp }(\psi))}\left\lVert\nabla \psi\right\rVert_{L^1} = 0,
\end{equation}
showing $\omega^{\varepsilon_n}(t) \to \omega(t)$ in $\mathcal{D}'(\mathbb{R}^2)$. Utilizing distributional convergence of the vorticity, we will show that for each $2\leq p<\infty, z \in \mathbb{R}^2$, $\lambda>0$, and $\psi \in L^{p'}(\mathbb{R}^2)$
\begin{equation}
\label{compact weak star convergence}
\lim_{n \to \infty} \int_{\mathbb{R}^2} \phi_{z,\lambda}(x)\omega^{\varepsilon_n}(t,x) \psi(x)dx = \int_{\mathbb{R}^2} \phi_{z,\lambda}(x)\omega(t,x) \psi(x)\,dx.
\end{equation}
 Let $2\leq p <\infty$ , we know that 
\begin{equation}
\label{rhs limit 1}
\sup_{n\in \mathbb{N}} \left\lVert\omega^{\varepsilon_n}(t)\right\rVert_{L^p(\text{supp }{\phi_{z,\lambda}})} \leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T,p).
\end{equation}
Since $\omega^{\varepsilon_n}(t) \to \omega(t)$ in $\mathcal{D}'(\mathbb{R}^2)$, by uniqueness of weak limits and reflexivity, a subsequence (which we relabel) of $\omega^{\varepsilon_n}(t)$ converges weakly to $\omega(t)$ in $L^p(\text{supp }{\phi_{z,\lambda}})$ and by weak lower semi-continuity one has
\begin{equation}
\label{rhs limit 2}
 \left\lVert\omega(t)\right\rVert_{L^p(\text{supp }{\phi_{z,\lambda}})} \leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T,p).
\end{equation}
Let $\psi \in L^{p'}(\mathbb{R}^2)$, by density, we construct a sequence $\{\psi_m\}_{m=1}^{\infty}\subseteq C_c^{\infty}(\mathbb{R}^2)$ such that $\psi_m \to\psi$ in $L^{p'}(\mathbb{R}^2)$. Then  
\begin{equation}
\label{rhs limit 2}
\begin{split}
&\left|\int_{\mathbb{R}^2} \phi_{z,\lambda}(x)(\omega^{\varepsilon_n}(t,x)-\omega(t,x))\psi(x)\,dx\right|  \leq \left|\int_{\mathbb{R}^2} \phi_{z,\lambda}(x)(\omega^{\varepsilon_n}(t,x)-\omega(t,x))\psi_m(x)\,dx\right|\\
&\hspace{3cm}+\left|\int_{\mathbb{R}^2} \phi_{z,\lambda}(x)(\omega^{\varepsilon_n}(t,x)-\omega(t,x))(\psi_m(x)-\psi(x))\,dx\right|=I+II.
\end{split}
\end{equation}
In order to estimate $I$, note that $\phi_{z,\lambda}\psi_m \in C^{\infty}_c(\mathbb{R}^2)$ which implies that 
\begin{equation}
\label{rhs limit 4}
\lim_{n \to \infty} \left|\int_{\mathbb{R}^2} \phi_{z,\lambda}(x)(\omega^{\varepsilon_n}(t,x)-\omega(t,x))\psi_m(x)\,dx\right|=0,
\end{equation}
as $\omega^{\varepsilon_n}(t) \to \omega(t)$ in $\mathcal{D}'(\mathbb{R}^2)$. To estimate $II$, from Hölder's inequality
\begin{equation}
\label{rhs limit 3}
II \leq \sup_{n\in \mathbb{N}}\left\lVert\phi_{z,\lambda}(\omega^{\varepsilon_n}(t)-\omega(t))\right\rVert_{L^p}\left\lVert\psi_m-\psi\right\rVert_{L^{p'}} \to 0 \text{ as } m \to \infty,
\end{equation}
where we made use of \eqref{rhs limit 1} and the fact that $\psi_m \to \psi$ in $L^{p'}(\mathbb{R}^2)$, which establishes \eqref{compact weak star convergence}. We now pass to the limit in \eqref{approx sti eq}. Let $x \in \mathbb{R}^2$ be fixed and $2<p<\infty$. Since $\text{supp}((aK)(x-\cdot)) \subseteq B_2(x)$ we note that $aK(x-y)=aK(x-y)\phi_{x,2}(y)$ and hence
\begin{equation}
\label{rhsp1}
\lim_{n \to \infty}\left|(aK) \ast (\omega^{\varepsilon_n}(t)-\omega(t))(x)\right| = \lim_{n \to \infty}\left|\int_{\mathbb{R}^2} (aK)(x-y) \phi_{x,2}(y)(\omega^{\varepsilon_n}(t,y)-\omega(t,y))\,dy \right|=0,
\end{equation}
where we made use of $y \mapsto aK(x-y) \in L^{p'}(\mathbb{R}^2)$. Since $\omega_0^{\varepsilon_n} = \rho_{\varepsilon_n} \ast \omega_0,$ where $\rho_{\varepsilon_n}$ is a standard mollifier, by a similar argument we easily see that 
\begin{equation}
\label{rhsp2}
\lim_{n \to \infty} \left|(aK) \ast (\omega^{\varepsilon_n}_0-\omega_0)(x)\right| \leq \left\lVertaK\right\rVert_{L^{p'}} \lim_{n \to \infty} \left\lVert\phi_{x,2}(y)(\omega_0^{\varepsilon_n}(y)-\omega_0(y))\right\rVert_{L^p_y}=0.
\end{equation}
We now estimate the difference coming from the integrand on the right-hand side of \eqref{approx sti eq}. We let $R>0$ to be chosen later. Using \eqref{uniform bounds approx}, one obtains
\begin{equation}
\label{rhsp3}
\begin{split}
&\sup_{0 \leq s \leq T}\left| \nabla\nabla^{\perp}((1-a)K)\ast \cdot(u^{\varepsilon_n}\otimes u^{\varepsilon_n}-u\otimes u)(s,x)\right|\\ &\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)\int_{|y| \leq R} |\nabla\nabla^{\perp}((1-a)K)(x-y)|\sup_{0 \leq s \leq T}|u^{\varepsilon_n}(s,y)-u(s,y)|\,dy\\
&\hspace{.5cm} +C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)\int_{|y| > R} |\nabla\nabla^{\perp}((1-a)K)(x-y)|dy\\
&\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)\left(\left\lVert\nabla\nabla^{\perp}((1-a)K)\right\rVert_{L^1}\sup_{0 \leq s \leq T} \left\lVert(u^{\varepsilon_n}-u)(s)\right\rVert_{L^{\infty}(B_R(0))} + \int_{|y| \geq R} \frac{dy}{|x-y|^3}\right)\\
&\leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T) \left(\sup_{0 \leq s \leq T}\left\lVert(u^{\varepsilon_n}-u)(s)\right\rVert_{L^{\infty}(B_R(0))} + \frac{1}{R-|x|}\right).
\end{split}
\end{equation}
Let $\eta>0$, we then choose $R>\max\left\{ 2|x|+4, \frac{4 C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)}{\eta}\right)$ and use \eqref{u convergence} to choose $N \in \mathbb{N}$ so that $\sup_{0 \leq s \leq T}\left\lVert(u^{\varepsilon_n}-u)(s)\right\rVert_{L^{\infty}(B_R(0))} \leq \frac{\eta}{2 C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}},T)}$. It follows that for any $n \geq N$
$$
\sup_{0 \leq s \leq T}\left| \nabla\nabla^{\perp}((1-a)K)\ast\cdot (u^{\varepsilon_n}\otimes u^{\varepsilon_n}-u\otimes u)(s,x)\right| <\eta,
$$
so that 
\begin{equation}
\label{rhsp4}
\lim_{n \to \infty }\left| \int_0^t\nabla\nabla^{\perp}((1-a)K)\ast\cdot (u^{\varepsilon_n}\otimes u^{\varepsilon_n}-u\otimes u)(s,x)\,ds\right|=0.
\end{equation}
Combining \eqref{rhsp1},\eqref{rhsp2}, \eqref{rhsp4}, and passing to the limit for the remaining terms in \eqref{approx sti eq} using \eqref{u convergence} and properties of mollification yields
\begin{equation}
\label{weak sfi}
u(t)=u_0 + (aK) \ast (\omega(t)-\omega_0) - \int_0^t \nabla \nabla^{\perp}((1-a)K) \ast \cdot(u \otimes u)(s)\,ds.
\end{equation}

\label{nice operator}[Theorem 5.3.3, \cite{grafakos2008classical}] Let $\mathcal{K} \in L^1_{loc}(\mathbb{R}^d\setminus\{0\})$ satisfy
\begin{equation}
\label{kernel assumption 1}
\sup_{R > 0} \int_{R \leq |x|\leq 2R} |\mathcal{K}(x)|\,dx=A_1,
\end{equation}
and
\begin{equation}
\label{kernel assupmtion 2}
\sup_{y \neq 0} \int_{|x| \geq 2|y|} |\mathcal{K}(x-y)-\mathcal{K}(x)|\,dx=A_2.
\end{equation}
Let $W \in \mathcal{S}'(\mathbb{R}^d)$ be defined as 
$$
\langle W,\varphi\rangle = \lim_{\varepsilon \to 0^+}\int_{|x| \geq \varepsilon}\mathcal{K}(x)\varphi(x)\,dx.
$$
Let $T$ be the operator associated to convolution with $W$, and assume that $T$ has a bounded extension mapping $L^r(\mathbb{R}^d)$ to itself for some $1<r<\infty$ with norm $B$. Then $T$ has a bounded extension operator from $L^p(\mathbb{R}^d)$ to itself for $1<p<\infty$ with norm
\begin{equation}
\label{operator norm}
\left\lVertT\right\rVert_{L^p \to L^p} \leq C(d)\max(p,(p-1)^{-1})(A_2+B),
\end{equation}
where $C(d)$ is a constant which does not depend on $p$.

\label{Local CZO}
Let $p \in (1,\infty)$, $\mathcal{K} \in C^2(\mathbb{R}^d\setminus\{0\})$ be homogeneous of degree $1-d$, and $f \in L^p_{ul}(\mathbb{R}^d)$. Then 
\begin{equation}
\label{local czo representation}
T_jf=\partial_{x_j} (a\mathcal{K} \ast f) = \text{p.v.}\int_{\mathbb{R}^d}\partial_{x_j} (a\mathcal{K})(x-y)f(y)\,dy + C_0(j,d,\mathcal{K})f,
\end{equation}
where
$$
C_0(j,d,K)=\int_{S^{d-1}}\mathcal{K}(\sigma)\sigma_jdS(\sigma),
$$
and the principal value represents a Calder\'{o}n-Zygmund operator. Furthermore, $T_j$ is a continuous linear operator on $L^p_{ul}(\mathbb{R}^d)$ and 
$$
\left\lVertT_jf\right\rVert_{L^p_{ul}} \leq \frac{C(j,d,\mathcal{K})p^2}{p-1}\left\lVertf\right\rVert_{L^p_{ul}}
$$

We first compute the distributional derivative of $a\mathcal{K}$. Let $\varphi \in C_0^{\infty}(\mathbb{R}^d)$, then
\begin{equation*}
\begin{split}
(\partial_{x_j}(a\mathcal{K}),\varphi) &= -\lim_{\varepsilon \to 0^+} \int_{|x| \geq \varepsilon} a(x)\mathcal{K}(x)\partial_{x_j}\varphi(x)\,dx \\
=& \lim_{\varepsilon \to 0^+} \left\{\int_{|x|\geq \varepsilon} \partial_{x_j}(a(x)\mathcal{K}(x)) \varphi(x)\,dx + \int_{|x|=\varepsilon} a(x)\mathcal{K}(x)\varphi(x)\frac{x_j}{|x|}dS\right\}.
\end{split}
\end{equation*}
In the latter integral, we perform the substitution $x=\varepsilon y$ to see that 
\begin{equation*}
\begin{split}
\lim_{\varepsilon \to 0^+}\int_{|x|=\varepsilon} a(x)\mathcal{K}(x)\varphi(x)\frac{x_j}{|x|}dS &= \lim_{\varepsilon \to 0^+}\int _{|y|=1}a(\varepsilon y) \varepsilon^{1-d}\mathcal{K}(y) \varphi(\varepsilon y) \frac{y_j}{|y|}\varepsilon^{d-1} \,dy\\
&= a(0)\varphi(0) \int_{|y|=1} \mathcal{K}(y)y_j\,dy\\
&=C_0(j,d,\mathcal{K})\varphi(0),
\end{split}
\end{equation*}
where in the second equality we used the Dominated Convergence Theorem, and in the last equality we used that $a(0)=1$, which establishes \eqref{local czo representation}. We make the observation that 
$$
\phi_z(\nabla(a\mathcal{K})\ast f) = \phi_{z}(\nabla(a\mathcal{K})\ast \phi_{z,8}f).
$$
Hence, showing that $T_j$ is a bounded linear operator on $L^p_{ul}(\mathbb{R}^d)$ will follow from showing that $T$ is a bounded linear operator on $L^p(\mathbb{R}^d)$. We first show that $T_j:L^2(\mathbb{R}^d) \to L^2(\mathbb{R}^d)$ is bounded. In particular, we aim to show that $\mathcal{F}(\partial_{x_j}(a\mathcal{K}))(\xi) \in L^{\infty}_{\xi}(\mathbb{R}^d)$ as
$$
\left\lVertT_jf\right\rVert_{L^2} \leq \left\lVert\mathcal{F}(\partial_{x_j} (a\mathcal{K}))(\xi)\right\rVert_{L^{\infty}_{\xi}}\left\lVertf\right\rVert_{L^2}.
$$
To see that $\mathcal{F}(\partial_{x_j}(a\mathcal{K}))(\xi) \in L^{\infty}_{\xi}(\mathbb{R}^d)$, we note that since $\mathcal{K} \in C^2(\mathbb{R}^d\setminus \{0\})$ is homogeneous of degree $1-d$, one has the usual bounds 
\begin{equation}
\label{k decay}
|\mathcal{K}(x)| \leq C(\mathcal{K})|x|^{1-d}, \quad |\nabla \mathcal{K}(x)| \leq C(\mathcal{K})|x|^{-d}, \quad |\nabla^2K(x)|\leq C(K)|\mathcal{K}|^{-d-1}.
\end{equation}
We consider two cases, one when $|\xi| \leq 1$ and the other when $|\xi| >1$. For $|\xi|>1$, we let $\chi$ be a standard bump function, and define $\chi_R(x)=\chi(x/R)$ for $R>0$. We have that 
\begin{equation}
\label{near field ak}
|\widehat{\chi_Ra\mathcal{K}}(\xi)| \leq \left\lVert\chi_Ra\mathcal{K}\right\rVert_{L^1}\leq C\int_{|x|\leq 2R} |x|^{1-d}\,dx \leq CR.
\end{equation} 
To estimate the far-field, for a fixed $\xi \in \mathbb{R}^d$ we define $e_{\xi}=\frac{\xi}{|\xi|}$ and $\partial_{e_{\xi}}=e_{\xi}\cdot \nabla$. Integration by parts twice yields the estimate
\begin{equation}
\label{far field ak 1}
\begin{split}
\left| \mathcal{F}\left((1-\chi_R)a\mathcal{K}\right)(\xi)\right| &= \left| \int_{\mathbb{R}^d} (1-\chi_R)(x)(a\mathcal{K})(x) e^{-2\pi i x \cdot \xi} \,dx\right|\\
&=
\frac{1}{4\pi^2|\xi|^2}\left| \int_{\mathbb{R}^d} (1-\chi_R)(x)(a\mathcal{K})(x) \partial_{e_{\xi}}^2e^{-2\pi i x \cdot \xi} \,dx\right|\\
&\leq \frac{1}{4\pi^2 |\xi|^2}\left\lVert\partial_{e_{\xi}}^2((1-\chi_R)(a\mathcal{K}))\right\rVert_{L^1}.
\end{split}
 \end{equation}
Since $a \in \mathcal{S}(\mathbb{R}^d)$, from the product rule we have
 \begin{equation}
 \begin{split}
 \label{far field ak 2}
 \left\lVert\partial_{e_{\xi}}^2((1-\chi_R)(a\mathcal{K}))\right\rVert_{L^1} & \leq \left\lVert(1-\chi_R)\partial_{e_{\xi}}^2(a\mathcal{K})\right\rVert_{L^1} + \left\lVert2(\partial_{e_\xi}\chi_R)(\partial_{e_{\xi}}(a\mathcal{K}))\right\rVert_{L^1} + \left\lVert (\partial_{e_{\xi}}^2\chi_R)a\mathcal{K}\right\rVert_{L^1}\\
 &\leq C\int_{R}^{\infty} \rho^{-2}\,d\rho + \frac{C}{R}\int_{R}^{2R} \rho^{-1}\,d\rho + \frac{C}{R^2} \int_{R}^{2R}d\rho\leq \frac{C}{R}.
 \end{split}
 \end{equation}
 Combining \eqref{near field ak}, \eqref{far field ak 1}, \eqref{far field ak 2}, and setting $R=\frac{1}{|\xi|}$ we find that 
 \begin{equation}
\label{xi less than 1 kernel}
|\mathcal{F}((a\mathcal{K}))(\xi)| \leq C(R+\frac{1}{|\xi|^2R})\leq \frac{C}{|\xi|}.
 \end{equation}
 It immediately follows that $\mathcal{F}(\partial_j(a\mathcal{K}))(\xi) \in L^{\infty}_{\xi}(\mathbb{R}^d)$ for $|\xi|>1$. To see the case when $|\xi|\leq 1$, we simply observe that $|\xi||\widehat{a\mathcal{K}}(\xi)| \leq \left\lVerta\mathcal{K}\right\rVert_{L^1}$ which gives the desired result.
 It remains to show that $\nabla(a\mathcal{K})$ satisfy \eqref{kernel assumption 1} and \eqref{kernel assupmtion 2}. We have that 
\begin{equation}
\begin{split}
\sup_{R\geq 0}\int_{R \leq |x| \leq 2R} |\nabla (a\mathcal{K})|\,dx &\leq \sup_{R \geq 0}\int_{R \leq |x|\leq 2R} |(\nabla a)\mathcal{K}| \,dx + \sup_{R \geq 0 } \int_{R \leq |x| \leq 2R} |a\nabla \mathcal{K}|dx \\
&\leq \int_{1 \leq |x|\leq 2} |(\nabla a)\mathcal{K}| \,dx + \left\lVerta\right\rVert_{L^{\infty}}\sup_{R \geq 0 } \int_{R \leq |x| \leq 2R} |\nabla \mathcal{K}|dx\\
&\leq C + C\sup_{R \geq 0}\int_{R}^{2R} \frac{1}{r^d}r^{d-1}\,dr = C(1+\ln(2)),
\end{split}
\end{equation}
where in the second inequality we utilized the support of $a$ and $\nabla a$. \eqref{kernel assupmtion 2} follows from the fact that $a \in \mathcal{S}(\mathbb{R}^2)$ and \eqref{k decay}. 
An application of Theorem \ref{nice operator} readily gives
\begin{equation*}
\left\lVert\phi_zT_jf\right\rVert_{L^p}=\left\lVert\phi_{z}T_j(\phi_{z,8}f)\right\rVert_{L^p}\leq \frac{C(j,d,\mathcal{K})p^2}{p-1}\left\lVert\phi_{z,8}f\right\rVert_{L^p},
\end{equation*}
and the result follows from taking a supremum over $z \in \mathbb{R}^d$.

Using a Littlewood-Paley decomposition, we have that 
\begin{equation}
\label{VG 1}
\left\lVert\nabla u(t)\right\rVert_{L^p_{ul}} \leq \left\lVert\Delta_{-1}\nabla u(t)\right\rVert_{L^p_{ul}} + \left\lVert\sum_{j \geq 0} \dot{\Delta}_j\nabla u(t)\right\rVert_{L^p_{ul}}.
\end{equation}
Estimating the low frequencies, one obtains 
\begin{equation}
\label{VG 2}
\phi_z(x)\Delta_{-1}\nabla u(t) = \phi_z(x)\int_{\mathbb{R}^2} \chi(x-y)\nabla u(t,y)\,dy =\phi_z(x) \int_{\mathbb{R}^2} (\nabla \chi)(x-y) u(t,y)\,dy,
\end{equation}
so that 
\begin{equation}
    \label{VG 3}
    \left\lVert\Delta_{-1} \nabla u(t)\right\rVert_{L^p_{ul}} \leq \left\lVert\nabla \chi\right\rVert_{L^1}\left\lVertu(t)\right\rVert_{L^p_{ul}} \leq C\left\lVertu(t)\right\rVert_{L^p_{ul}}.
\end{equation}
To estimate the high frequencies we use \eqref{FLSI} and that $\dot{\Delta}_ju_0=-\dot{\Delta}_j\nabla^{\perp}(-\Delta)^{-1}\omega_0$ 
\begin{equation}
\begin{split}
\label{VG 4}
\left\lVert\sum_{j \geq 0} \dot{\Delta}_j\nabla u(t)\right\rVert_{L^p_{ul}} &\leq \left\lVert\sum_{j \geq 0} \dot{\Delta}_j\nabla u_0 + \sum_{j \geq 0} \dot{\Delta}_j \nabla(aK)\ast (\omega(t)-\omega_0)\right\rVert_{L^p_{ul}}\\
&\hspace{-2cm}+\int_0^t \left\lVert\sum_{j \geq 0} \dot{\Delta}_j \nabla\nabla\nabla^{\perp}((1-a)K) \ast\cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}\,ds\\
&\hspace{-2cm}= 
\left\lVert\sum_{j \geq 0} (\dot{\Delta}_j\nabla K) \ast\omega_0+ \sum_{j \geq 0} \dot{\Delta}_j \nabla(aK)\ast (\omega(t)-\omega_0)\right\rVert_{L^p_{ul}}\\
&\hspace{-2cm}+\int_0^t \left\lVert\sum_{j \geq 0} \dot{\Delta}_j \nabla\nabla\nabla^{\perp}((1-a)K) \ast\cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}\,ds\\
&\hspace{-2cm} \leq \left\lVert\sum_{j \geq 0} \dot{\Delta}_j\nabla((1-a)K)\ast\omega_0\right\rVert_{L^p_{ul}} + \left\lVert\sum_{j \geq 0} \dot{\Delta}_j \nabla(aK)\ast \omega(t)\right\rVert_{L^p_{ul}}\\
&\hspace{-2cm}+\int_0^t \left\lVert\sum_{j \geq 0} \dot{\Delta}_j \nabla\nabla\nabla^{\perp}((1-a)K) \ast\cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}\,ds
:= I+II+III.
\end{split}
\end{equation}
\textbf{Estimate of $I$:} Using that $\omega_0=\nabla^{\perp}\cdot u_0$, associativity of convolution, and slightly abusing notation we have that 
\begin{equation}
    \label{VG 7}
    \begin{split}
I &=  \left\lVert\sum_{j \geq 0} \dot{\Delta}_j\nabla\nabla^{\perp}((1-a)K)\ast\cdot u_0\right\rVert_{L^p_{ul}}\\
&\leq \left\lVert\Delta_{-1}\nabla\nabla^{\perp}((1-a)K)\ast\cdot u_0\right\rVert_{L^p_{ul}} + \left\lVert\nabla\nabla^{\perp}((1-a)K)\ast\cdot u_0\right\rVert_{L^p_{ul}} \\
&\leq C\left\lVertu_0\right\rVert_{L^p_{ul}}.
    \end{split}
\end{equation}
\textbf{Estimate of $II$:} A direct application of Proposition \ref{Local CZO} yields
\begin{equation}
\label{VG 8}
\begin{split}
II & \leq \left\lVert\Delta_{-1}\nabla(aK) \ast \omega(t)\right\rVert_{L^p_{ul}} + \left\lVert\nabla (aK)\ast \omega(t)\right\rVert_{L^p_{ul}} \leq \frac{C(d)p^2}{p-1}\left\lVert\omega(t)\right\rVert_{L^p_{ul}}.
\end{split}
\end{equation}
\textbf{Estimate of $III$:} We have that 
\begin{equation}
\label{VG 9}
\begin{split}
III & = \int_0^t \left\lVert\sum_{j \geq 0} \dot{\Delta}_j \nabla\nabla\nabla^{\perp}((1-a)K) \ast\cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}\,ds\\
&\leq \int_0^t \left\{\left\lVert\nabla\nabla\nabla^{\perp}((1-a)K) \ast \cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}+{\left\lVert\Delta_{-1}\nabla\nabla\nabla^{\perp}((1-a)K) \ast \cdot (u\otimes u)(s)\right\rVert_{L^p_{ul}}} \right\}\,ds\\
&\leq Ct\sup_{0 \leq s \leq t} \left\{\left\lVertu(s)\right\rVert_{L^{p}_{ul}}\left\lVertu(s)\right\rVert_{L^{\infty}}\right\}
\end{split}
\end{equation}
Combining \eqref{VG 3}, \eqref{VG 4}, \eqref{VG 7}, \eqref{VG 8}, and \eqref{VG 9} yields
$$
\left\lVert\nabla u(t)\right\rVert_{L^p_{ul}} \leq \frac{C(d)p^2}{p-1}\left\lVert\omega(t)\right\rVert_{L^p_{ul}}+C\left(\left\lVertu(t)\right\rVert_{L^p_{ul}}+\left\lVertu_0\right\rVert_{L^p_{ul}}\right)+Ct\sup_{0 \leq s \leq t}\left\{\left\lVertu(s)\right\rVert_{L^p_{ul}} \left\lVertu(s)\right\rVert_{L^{\infty}} \right\}.
$$

Additionally, if we assume that $\omega = \text{curl }u \in L^{\infty}([0,T];Y^{\theta}_{ul}(\mathbb{R}^2))$, as an immediate corollary of Theorem \ref{velocity gradient estimate}, using that $\frac{p^2}{p-1} \geq 1, \theta(p) \geq 1$, and the regularity of $u$ and $\omega$, we obtain the estimate
\begin{equation}
\label{best velocity gradient estimate}
\sup_{0 \leq t \leq T} \left\lVert\nabla u(t)\right\rVert_{L^p_{ul}} \leq C(\left\lVertu_0\right\rVert_{L^{\infty}},\left\lVert\omega_0\right\rVert_{Y^{\theta}_{ul}}, d, T) p\theta(p)  \quad \text{ for all } 2\leq p<\infty.
\end{equation}
